import React from 'react';
import { Link } from 'react-router-dom';
import '../index.css';

const Home = () => (
  <div className="home-container">
    <header className="hero">
      <h1>👨‍💻 My Portfolio</h1>
      <p>Hi! I'm a passionate <span className="highlight">MERN Developer</span></p>
    </header>

    <section className="section">
      <h2>💼 My Projects</h2>
      <div className="card-container">
        <div className="card">
          <h3>Project A</h3>
          <p>A modern web app built with React and Node.js</p>
        </div>
        <div className="card">
          <h3>Project B</h3>
          <p>REST API service using Express and MongoDB</p>
        </div>
      </div>
    </section>

    <section className="section">
      <h2>🛠️ Skills</h2>
      <p className="skills">React • Node.js • MongoDB • Express</p>
    </section>

    <div className="center">
      <Link to="/buy">
        <button className="buy-btn">💳 Buy My Resume</button>
      </Link>
    </div>
  </div>
);

export default Home;
